import {incrementalRecord} from './incremental-registry.js';
import {annualTextHTML} from './annual-localization.js';
import {displayNumber,precisionInputAttributes,readPrecisionInput,bindPrecisionInput} from './number-display.js';
import {annualRevenueGrowthChartHTML,annualFCFFGrowthChartHTML} from './annual-revenue-growth-chart.js';
import {NFLX_MESSAGES} from './nflx-messages.js';
import {NFLX_NUMERIC_POLICY_KEYS,NFLX_SCHEDULE_KEYS,NFLX_ACKS} from './nflx-financial-engine.js';
export {NFLX_MESSAGES} from './nflx-messages.js';
const a=k=>annualTextHTML(NFLX_MESSAGES[k][0]),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),n=x=>displayNumber(x,2),object=x=>x!==null&&typeof x==='object'&&!Array.isArray(x),finite=x=>typeof x==='number'&&Number.isFinite(x);
const paragraph=(r,k)=>`<p>${annualTextHTML(r.prose[k].en)}</p>`;
// Keep rejected text serializable and visible through reload, locale and Undo.
const numericAttributes=value=>precisionInputAttributes(value,1,typeof value==='string'?value:undefined)+(typeof value==='string'?' aria-invalid="true"':'');
export function nflxSitePolicyTemplate(r=incrementalRecord('NFLX')){const p=structuredClone(r.policyTemplate);p.policy_label='Explicit restricted source convention';p.debt_valuation_basis='face_principal_excluding_financing_derivatives';p.debt_value=14372;p.financing_interest_rate_derivative_reserve=13.574;NFLX_ACKS.forEach(k=>p[k]=true);for(const k of NFLX_SCHEDULE_KEYS)p[k]=Object.fromEntries(Array.from({length:k.includes('retained_')?11:10},(_,i)=>[String(i+2026),null]));return p;}
export function nflxPolicyEditorHTML(d){
 if(d?.ticker!=='NFLX')return '';const r=incrementalRecord('NFLX'),p=d.nflxPolicy,scheduleLabels=['awardSchedule','futureSchedule','otherSchedule','claimSchedule'];
 const fields=object(p)?`<div class="research-field-grid">${NFLX_NUMERIC_POLICY_KEYS.map(k=>`<label>${a(k)}<input type="text" inputmode="decimal" data-precision-grammar="annual" data-nflx-policy="${k}" ${numericAttributes(p[k])} aria-describedby="nflx-policy-help"></label>`).join('')}<label>${a('awardDate')}<input type="date" data-nflx-award-date value="${esc(p.existing_award_latest_recognition_date??'')}" min="2026-07-01" max="2029-06-30"></label></div>${NFLX_SCHEDULE_KEYS.map((key,i)=>`<details><summary>${a(scheduleLabels[i])}</summary><div class="research-field-grid">${Array.from({length:key.includes('retained_')?11:10},(_,j)=>String(j+2026)).map(y=>`<label>${esc(y)}<input type="text" inputmode="decimal" data-precision-grammar="annual" data-nflx-schedule="${key}" data-nflx-year="${y}" ${numericAttributes(object(p[key])?p[key][y]:null)} aria-label="${esc(y)}"></label>`).join('')}</div></details>`).join('')}`:'';
 const ledger=d.nflxLedger,raw=typeof ledger==='string'?ledger:JSON.stringify(ledger,null,2);
 return `<section class="research-card" id="nflx-policy-tool"><h3>${a('title')}</h3><p>${a(p===null?'none':'selected')}</p><div class="result-actions"><button type="button" class="quiet" data-nflx-example>${a('example')}</button><button type="button" class="quiet" data-nflx-empty>${a('empty')}</button><button type="button" class="quiet" data-nflx-clear>${a('clear')}</button></div><div id="nflx-policy-help"><p>${a('nulls')}</p>${paragraph(r,'claims')}${paragraph(r,'awards')}${paragraph(r,'tax')}${paragraph(r,'funding')}</div>${fields}<details><summary>${a('ledger')}</summary>${paragraph(r,'financing')}<div class="result-actions"><button type="button" class="quiet" data-nflx-ledger-open>${a('openLedger')}</button><button type="button" class="quiet" data-nflx-ledger-clear>${a('clearLedger')}</button></div>${ledger===null?`<p>${a('ledgerNone')}</p>`:`<label for="nflx-ledger-json">${a('ledgerInput')}</label><textarea id="nflx-ledger-json" rows="18" spellcheck="false">${esc(raw)}</textarea>`}</details></section>`;
}
export function bindNflxPolicy(root,d,{save,rerender,updateResults,remember,endEdit}={}){
 if(d?.ticker!=='NFLX')return;const r=incrementalRecord('NFLX');
 const action=(selector,name,fn)=>{const el=root.querySelector(selector);if(el)el.onclick=()=>{remember?.(name);fn();save?.();rerender?.();endEdit?.();root.querySelector(selector)?.focus({preventScroll:true});};};
 action('[data-nflx-example]','nflx-policy-example',()=>d.nflxPolicy=structuredClone(r.policyExample));action('[data-nflx-empty]','nflx-policy-empty',()=>d.nflxPolicy=nflxSitePolicyTemplate());action('[data-nflx-clear]','nflx-policy-clear',()=>d.nflxPolicy=null);action('[data-nflx-ledger-open]','nflx-ledger-open',()=>d.nflxLedger=structuredClone(r.rollforwardTemplate.user_assumptions_required));action('[data-nflx-ledger-clear]','nflx-ledger-clear',()=>d.nflxLedger=null);
 const bind=(selector,read,edit)=>root.querySelectorAll(selector).forEach(el=>{el.onfocus=()=>endEdit?.();el.onblur=()=>endEdit?.();el.oninput=()=>{remember?.('nflx:'+selector+':'+(el.dataset.nflxPolicy||el.dataset.nflxSchedule||'')+':'+(el.dataset.nflxYear||''));edit(el,read(el));save?.();updateResults?.();};if(selector!=='[data-nflx-award-date]')bindPrecisionInput(el);});
 const numeric=el=>{if(el.value.trim()===''){el.setAttribute('aria-invalid','false');return null;}const value=readPrecisionInput(el);el.setAttribute('aria-invalid',String(!finite(value)));return finite(value)?value:el.value;};
 bind('[data-nflx-policy]',numeric,(el,value)=>{if(object(d.nflxPolicy)&&NFLX_NUMERIC_POLICY_KEYS.includes(el.dataset.nflxPolicy))d.nflxPolicy[el.dataset.nflxPolicy]=value;});
 bind('[data-nflx-schedule]',numeric,(el,value)=>{const k=el.dataset.nflxSchedule;if(object(d.nflxPolicy)&&NFLX_SCHEDULE_KEYS.includes(k)){if(!object(d.nflxPolicy[k]))d.nflxPolicy[k]={};d.nflxPolicy[k][el.dataset.nflxYear]=value;}});
 bind('[data-nflx-award-date]',el=>el.value||null,(el,value)=>{if(object(d.nflxPolicy))d.nflxPolicy.existing_award_latest_recognition_date=value;});
 bind('[data-nflx-content-timing]',numeric,(el,value)=>d.nflxContentTiming=value);
 const text=root.querySelector('#nflx-ledger-json');if(text){text.onfocus=()=>endEdit?.();text.onblur=()=>endEdit?.();text.oninput=()=>{remember?.('nflx-ledger-json');try{d.nflxLedger=JSON.parse(text.value);}catch{d.nflxLedger=text.value;}save?.();updateResults?.();};}
}
export function nflxContentTimingHTML(d){return d?.ticker==='NFLX'?`<div class="research-field-grid"><label>${a('contentTiming')}<input type="text" inputmode="decimal" data-precision-grammar="annual" data-nflx-content-timing ${numericAttributes(d.nflxContentTiming)}></label></div><p class="micro">${a('contentTimingHelp')}</p>`:'';}
export function nflxAllocationHTML(b){
 if(b?.ticker!=='NFLX')return '';const r=incrementalRecord('NFLX'),v=b.nflxAllocation,l=b.nflxLedger,cap=l?.projected_capital;
 return `<div class="nflx-allocation">${paragraph(r,'claims')}${paragraph(r,'awards')}${paragraph(r,'tax')}${finite(v.existing_award_expense_aftertax_pv)?`<p>${a('awardPV')}: ${n(v.existing_award_expense_aftertax_pv)} USDm<br>${a('adjustedEV')}: ${n(v.allocation_adjusted_operating_ev)} USDm<br>${a('optionClaim')}: ${n(v.option_value_proxy)} USDm<br>${a('minimumFunding')}: ${n(Math.min(...v.funding_stress.map(x=>x.annual_cash_capacity_proxy)))} USDm</p>`:''}<p class="nflx-ledger-result">${!l?a('ledgerNone'):!cap?a('ledgerMissing'):`${a('ledgerReady')}<br>${a('cash')}: ${n(cap.cash_and_short_investments)} USDm<br>${a('debt')}: ${n(cap.debt_face)} USDm<br>${a('shares')}: ${n(cap.common_shares_m)}`}</p>${paragraph(r,'financing')}</div>`;
}
export function nflxCalculationHTML(op){const rows=op?.nflxCalculation?.forecast;if(!rows)return '';return `<div class="research-table-scroll"><table class="research-table"><caption>${a('calculation')}</caption><thead><tr>${['fiscalYear','amort','contentCash','noncontentDa','ppe','nwc'].map(k=>`<th scope="col">${a(k)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${esc(r.period_end)}</th>${['content_amortization','content_cash_payments','noncontent_da','ppe_capex','noncontent_nwc_investment'].map(k=>`<td>${n(r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
export function nflxHistoryHTML(d,key='growth'){
 if(d?.ticker!=='NFLX'||!['growth','profitability','capital','history'].includes(key))return '';const r=incrementalRecord('NFLX'),cols=key==='growth'?[['revenue','revenue']]:key==='profitability'?[['ebit','ebit']]:[['cfo','cfo'],['amort','content_amortization'],['contentCash','content_cash_payments_derived'],['ppe','ppe_purchases']];
 return `<section class="research-card nflx-history-reference" data-nflx-history="${key}"><h4>${a('historyTitle')}</h4>${paragraph(r,'history')}${paragraph(r,key==='capital'?'capital':key==='profitability'?'profitability':'growth')}<div class="research-table-scroll" tabindex="0"><table class="research-table"><caption>${a('historyTitle')} · USDm</caption><thead><tr><th scope="col">${a('fiscalYear')}</th>${cols.map(([k])=>`<th scope="col">${a(k)}</th>`).join('')}</tr></thead><tbody>${r.history.map(row=>`<tr><th scope="row">${esc(row.fiscalYear)}</th>${cols.map(([,k])=>`<td>${finite(row[k])?n(row[k]):a('missing')}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p><a href="${esc(r.identity.provenancePath)}" target="_blank" rel="noopener">${a('historySource')}</a></p></section>`;
}
export function nflxRevenueGrowthHTML(d,rows){return `<p>${a('stub')}</p>`+annualRevenueGrowthChartHTML(rows,{anchor:d.anchor,terminalGrowth:d.terminal.growth});}
export function nflxFCFFGrowthHTML(rows){return annualFCFFGrowthChartHTML(rows.map((r,i)=>i?r:{...r,fcff:null}),{baselineHTML:a('stub')});}
